assert set(P.keys()) == set(EXPECTED), "prediction id set mismatch"
for cid in EXPECTED:
    rec = P[cid]
    for k in ("case_id","prediction_text","basis","confidence","trigger"):
        assert k in rec, (cid,k)
    for k in ("changed_main","reserve_used","disputed","reason"):
        assert k in rec["trigger"], (cid,k)
    (OUT/f"{cid}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")

ok = 0
for cid in EXPECTED:
    rec = json.loads((OUT/f"{cid}.json").read_text(encoding="utf-8"))
    assert rec["case_id"] == cid and rec["prediction_text"] and rec["basis"] and isinstance(rec["confidence"], float)
    assert set(rec["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    ok += 1
print("written_and_verified", ok)
print("changed_main", sum(1 for r in P.values() if r["trigger"]["changed_main"]))
print("reserve_used", sum(1 for r in P.values() if r["trigger"]["reserve_used"]))
print("disputed", sum(1 for r in P.values() if r["trigger"]["disputed"]))
